<script setup lang="ts">import {ref,onMounted} from 'vue';import {request} from '../api/client';import {useTask} from '../hooks/useTask';import {date} from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';const rows=ref<{id:number;actor:string;action:string;status_code:number;created_at:string}[]>([]),{error,perform}=useTask();async function load(){rows.value=await request('/audit')}onMounted(()=>perform(load));</script><template><PageHeading no="06" title="过程留档" sub="资料写入、审阅与分发，把重要操作留在研究过程里。"/><ErrorNotice :error="error"/><div class="section-line"><p class="muted">最近100次写入与导出操作，包含权限拒绝。</p><button @click="perform(load)">刷新留档 ↻</button></div><div class="table-scroll"><table><thead><tr><th>编号</th><th>操作者</th><th>操作</th><th>HTTP结果</th><th>时间</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>LOG {{r.id}}</td><td>{{r.actor}}</td><td>{{r.action}}</td><td><span :class="['status',r.status_code>=400?'failed':'completed']">{{r.status_code}}</span></td><td>{{date(r.created_at)}}</td></tr></tbody></table></div><p v-if="!rows.length" class="empty">首次写入或下载后，真实操作会出现在此。</p><aside class="margin-note">此处是应用层操作记录。权重情景的原始数值在“结果与扰动 / 情景留档”逐次保存，读取页面不会制造写入记录。</aside></template>